export const MOCK_QUESTIONS: Question[] = RAW_QUESTIONS.map((row, index) => {
  const hasVignette = row.length === 6;
  const offset = hasVignette ? 1 : 0;
  const id = `q${index + 1}`;
  return {
    id: `q${index + 1}`,
    topicId: "mock",
    ...(hasVignette ? { vignette: row[0] } : {}),
    stem: row[offset],
    optionA: row[offset + 1],
    optionB: row[offset + 2],
    optionC: row[offset + 3],
    correctAnswer: row[offset + 4],
    explanation:
      MOCK_1_SESSION_1_EXPLANATIONS[`q${index + 1}`] ??
      `Correct answer: ${row[offset + 4]}`,
    difficulty: "medium",
    ...MOCK_1_SESSION_1_QUESTION_OVERRIDES[id],
  } as Question;
});
export const MOCK_EXAMS: MockExam[] = RAW_EXAMS.map(([id, title, description, firstId, lastId]) => {
  const first = Number(firstId.slice(1));
  const last = Number(lastId.slice(1));
  return {
    id,
    title,
    description,
    questionCount: last - first + 1,
    durationMinutes: 135,
    level: "I",
    createdAt: "2026-05-19T00:00:00Z",
    questionIds: Array.from({ length: last - first + 1 }, (_, index) => `q${first + index}`),
  };
});
